//! Shared static assets embedded at compile time + their serve handlers.

use axum::http::StatusCode;

/// Datastar client — compile-time embedded, shipped with the daemon binary.
/// Upgraded by committing a new apps/shipd/assets/datastar.js.
const DATASTAR_JS: &str = include_str!("../../assets/datastar.js");

/// Ship web-component element bundle (Lit + every `<ship-*>` primitive and
/// domain element). Generated by `bun run --filter @ship/ui bundle:elements`, which
/// runs esbuild over `packages/ship-set/src/web-components/index.ts`. Daemon-
/// rendered views load this once and every subsequent SSE fragment that
/// references a `<ship-*>` element renders immediately.
const SHIP_ELEMENTS_JS: &str = include_str!("../../assets/ship-elements.js");

/// Git-view island bundle (diff renderer, blame strip, etc.).
const SHIP_GIT_JS: &str = include_str!("../../assets/ship-git.js");

/// Jinja macros SDK manifest (machine-readable). Built by
/// `scripts/build-jinja-docs.mjs` (wired as `bun run build:jinja-docs`).
/// Editor tooling fetches this JSON for signature + argument autocomplete.
const JINJA_MACROS_JSON: &str = include_str!("../../../../packages/ship-set/jinja-macros.json");

/// Human-readable Jinja SDK macro manifest, grouped by category.
/// Generated alongside jinja-macros.json.
const JINJA_MACROS_MD: &str = include_str!("../../../../packages/ship-set/jinja-macros.md");

/// Custom Elements Manifest (CEM) — machine-readable catalog of every
/// `<ship-*>` element's attrs, slots, events, and CSS custom properties.
/// Generated by `bun run --filter @ship/ui manifest`. Consumed by IDE tooling
/// for attribute autocomplete.
const SHIP_ELEMENTS_MANIFEST: &str = include_str!("../../../../packages/ship-set/custom-elements.json");

/// Aggregated Custom Elements Manifest for SUI components (one module per
/// `<sui-*>` tag). Built by `scripts/build-bundles.mjs` from the
/// per-component CEMs in `packages/ui-components/src/<tag>/` and written
/// to `crates/sui/ship-sui/assets/sui-custom-elements.json`. The
/// previous path (`apps/shipd/assets/sui-custom-elements.json`) was a
/// 2-byte `{}` placeholder — every daemon binary shipped without the
/// real catalog, so ship-ui-studio rendered an empty component list.
const SUI_ELEMENTS_MANIFEST: &str =
    include_str!("../../../../crates/sui/ship-sui/assets/sui-custom-elements.json");

/// Token-efficient compact catalog. ~4KB vs the 189KB full CEM.
/// Derived from the CEM by `bun run --filter @ship/ui catalog`. This is what
/// agents should read into their context by default.
const SHIP_ELEMENTS_CATALOG: &str = include_str!("../../../../packages/ship-set/catalog.md");

/// Shared design tokens + base styles for all daemon-served views.
/// Canonical OKLCH palette is sourced from `@ship/ui/tokens.css` so Studio,
/// daemon views, and web components can never drift. View-scoped base rules
/// live alongside in `assets/view-tokens.css`.
const VIEW_TOKENS_CSS: &str = concat!(
    include_str!("../../../../packages/ship-set/src/tokens.css"),
    "\n",
    include_str!("../../assets/view-tokens.css"),
    "\n",
    // Per-theme overrides — :root[data-theme='paper'] etc. Applied by
    // the theme picker toggling `data-theme` + `.dark` on <html>.
    // Without this, `applyTheme` only switches light ↔ dark because
    // every other theme's overrides are invisible to the browser.
    include_str!("../../../../packages/ship-set/src/themes.css"),
);

/// GET /api/v1/runtime/assets/datastar.js
#[utoipa::path(
    operation_id = "serveDatastarJs",
    get,
    path = "/api/assets/datastar.js",
    responses(
        (status = 200, description = "Datastar client bundle", content_type = "application/javascript"),
        (status = 500, description = "server error", body = crate::wire::ErrorResponse),
    ),
    security(),
    tag = "views"
)]
pub async fn serve_datastar_js() -> axum::response::Response {
    axum::response::Response::builder()
        .status(StatusCode::OK)
        .header(axum::http::header::CONTENT_TYPE, "application/javascript; charset=utf-8")
        .header(axum::http::header::CACHE_CONTROL, "public, max-age=3600, immutable")
        .body(axum::body::Body::from(DATASTAR_JS))
        .unwrap()
}

/// GET /api/v1/runtime/assets/view-tokens.css
#[utoipa::path(
    operation_id = "serveViewTokens",
    get,
    path = "/api/assets/view-tokens.css",
    responses(
        (status = 200, description = "Design tokens + base CSS for views", content_type = "text/css"),
        (status = 500, description = "server error", body = crate::wire::ErrorResponse),
    ),
    security(),
    tag = "views"
)]
pub async fn serve_view_tokens() -> axum::response::Response {
    axum::response::Response::builder()
        .status(StatusCode::OK)
        .header(axum::http::header::CONTENT_TYPE, "text/css; charset=utf-8")
        // No-cache so theme/token edits land on the next load without
        // needing a hard refresh. Production builds can add ETags.
        .header(axum::http::header::CACHE_CONTROL, "no-cache")
        .body(axum::body::Body::from(VIEW_TOKENS_CSS))
        .unwrap()
}

